//!
//! The ravenlibc external ABI: scalar types, Linux-valued constants and `#[repr(C)]` records.
//!
//! Every value and every struct layout is generated by `raven-libc-hdrgen` from
//! `libc/ravenlibc/abi/*.toml`, which is the single source of truth for doc 14 part A. This
//! crate is the Rust view of that data; `abi/generated/include` is the C view. `cargo xtask
//! libc-lint` and `raven-libc-hdrgen check` keep both in sync with the TOML.
//!
//! The crate is `no_std`, has no runtime dependencies and is class P (`forbid(unsafe_code)`).
//! It does not call a system primitive; `raven-libc-platform` owns the implementations.

#![cfg_attr(not(test), no_std)]
#![forbid(unsafe_code)]
#![deny(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::unreachable,
    clippy::todo,
    clippy::unimplemented
)]

pub mod arch;
pub mod errno;
#[allow(missing_docs)] // generated constant names are their own documentation
pub mod generated;
pub mod layout;

pub use generated::{
    fcntl, limits, misc, mman, netinet, poll, pthread, resource, signal, socket, stat, structs,
    sysconf, time, types,
};
